arguments.command:
curl -s "https://api.bls.gov/publicAPI/v2/timeseries/data/CUUR0000SA0?startyear=1992&endyear=1994" -H "Content-type: application/json" 2>/dev/null | python3 -c "
import sys,json
d=json.load(sys.stdin)
data = d['Results']['series'][0]['data']

# Group by year
years = {}
for item in data:
    y = item['year']
    if y not in years:
        years[y] = []
    if item['period'].startswith('M'):
        years[y].append(float(item['value']))

for y in ['1992', '1993', '1994']:
    if y in years:
        avg = sum(years[y]) / len(years[y])
        print(f'{y}: {avg:.2f} (from {len(years[y])} months)')
"
